sections.body:
保存为 triage-audit.mjs，运行 node triage-audit.mjs，无额外依赖。每行是“核验标签、分数、同类记录数量”，只有 score≥threshold 才入选；分数限定在 0–1，但不宣称它已校准成概率。

```js
/**
 * @file Audit weighted ticket scores without hiding false positives or missed cases.
 * @author liliwei
 * @date 2026-11-24
 * @LastEditors liliwei
 * @LastEditTime 2026-11-24
 */
/**
 * @param {Array<[number, number, number]>} rows [confirmedLabel, score, count].
 * @param {number} threshold Inclusive score cutoff in [0, 1].
 * @param {number} capacity Review slots in the same reporting window.
 * @returns {object} Counts, ratios and capacity check; no queue truncation.
 */
export function audit(rows, threshold, capacity) {
  if (!Array.isArray(rows) || !Number.isFinite(threshold) ||
      threshold < 0 || threshold > 1 ||
      !Number.isSafeInteger(capacity) || capacity < 0) {
    throw new Error('Invalid audit arguments');
  }
  const c = { tp: 0, fp: 0, tn: 0, fn: 0 };
  let total = 0;
  for (const row of rows) {
    if (!Array.isArray(row) || row.length !== 3) throw new Error('Invalid row');
    const [label, score, count] = row;
    if (![0, 1].includes(label) || !Number.isFinite(score) || score < 0 ||
        score > 1 || !Number.isSafeInteger(count) || count <= 0 ||
        !Number.isSafeInteger(total + count)) throw new Error('Invalid data');
    total += count;
    const selected = score >= threshold;
    c[label === 1 ? (selected ? 'tp' : 'fn') : (selected ? 'fp' : 'tn')] += count;
  }
  const queued = c.tp + c.fp;
  /** @returns {number|null} Null means the denominator has no observations. */
  const ratio = (n, d) => d ? n / d : null;
  return { ...c, total, queued, withinCapacity: queued <= capacity,
    accuracy: ratio(c.tp + c.tn, total),
    precision: ratio(c.tp, queued), recall: ratio(c.tp, c.tp + c.fn),
    falsePositiveRate: ratio(c.fp, c.fp + c.tn) };
}

// Original synthetic score bins; these are not model predictions or real tickets.
export const field = [
  [1, 0.95, 70], [1, 0.70, 20], [1, 0.20, 10],
  [0, 0.95, 10], [0, 0.70, 89], [0, 0.20, 9801]
];
const balanced = field.map(([y, s, n]) => [y, s, y === 1 ? n * 99 : n]);
for (const [name, rows, threshold] of [
  ['balanced', balanced, 0.5], ['field', field, 0.5],
  ['higher', field, 0.9], ['none', field, 1]
]) console.log(JSON.stringify({ name, threshold, ...audit(rows, threshold, 100) }));
```

withinCapacity 只比较数量，不模拟客服速度、到达时刻或排队等待；代码也不会截成前 100 份。没有入选时查准率返回 null，没有正类时召回率返回 null，都不能写成 100%。
